import fs from 'node:fs';
import {gunzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
const html = gunzipSync(Buffer.from('', 'base64'));
if (createHash('sha256').update(html).digest('hex') !== '7cd661fe356382feba740145ef2f7ea93048051133ec7178177040ee79104a4f') throw Error('Thermal viewer checksum mismatch');
fs.mkdirSync('dist/thermal', {recursive:true});
fs.writeFileSync('dist/thermal/index.html', html);
